    for (i = 100; i <= n; i++) {
        a = i / 100;
        b = i / 10 % 10;
        c = i % 10;
        if (a * a * a + b * b * b + c * c * c == i) {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, i, j, sum, count = 0;
    scanf("%d", &n);
    for (i = 2; i <= n; i++) {
        sum = 1;
        for (j = 2; j * j <= i; j++) {
            if (i % j == 0) {
                sum += j;
                if (j != i / j) {
                    sum += i / j;
                }
            }
        }
        if (sum == i) {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}

