int find(int a[], int l, int r, int x) {
    int mid;
    if (l > r) {
        return 0;
    }
    mid = (l + r) / 2;
    if (a[mid] == x) {
        return mid + 1;
    }
    if (a[mid] > x) {
        return find(a, l, mid - 1, x);
    }
    return find(a, mid + 1, r, x);
}

