int daynum(int y, int m, int d) {
    int md[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int total = 0;
    for (int yy = 1900; yy < y; yy++) {
        int leap = (yy % 4 == 0 && yy % 100 != 0) || (yy % 400 == 0);
        total += leap ? 366 : 365;
    }
    int leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    md[2] = leap ? 29 : 28;
    for (int mm = 1; mm < m; mm++) total += md[mm];
    total += d - 1;
    return total;
}

