    for (int i = cnt - 1; i >= 0; i--) printf("%d", r[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, r[105], cnt = 0;
    scanf("%d", &n);
    if (n == 0) {
        printf("0\n");
        return 0;
    }
    while (n > 0) {
        r[cnt++] = n % 16;
        n /= 16;
    }
    for (int i = cnt - 1; i >= 0; i--) {
        if (r[i] < 10) printf("%d", r[i]);
        else printf("%c", 'A' + (r[i] - 10));
    }
    printf("\n");
    return 0;
}

